namespace Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Infrastructure\Driver;

use Psr\Container\ContainerInterface;
use Override;
use Slim\Routing\RouteCollectorProxy;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Infrastructure\Driver\Rest\SmtpOutboundConfigAllowController;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Infrastructure\Driver\Rest\SmtpOutboundConfigListController;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Infrastructure\Driver\Rest\SmtpOutboundConfigCreateController;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Infrastructure\Driver\Rest\SmtpOutboundConfigRetrieveController;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Infrastructure\Driver\Rest\SmtpOutboundConfigUpdateController;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Infrastructure\Driver\Rest\SmtpOutboundConfigDeleteController;
use Civi\Lughauth\Shared\Security\Rbac\Handler;
use Civi\Lughauth\Shared\Infrastructure\MicroPlugin;
use Civi\Lughauth\Shared\Security\SecurityPlugin;
use Civi\Lughauth\Shared\Infrastructure\StartupProcessor;
use Civi\Lughauth\Shared\Event\EventListenersRegistrarInterface;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Application\Service\Visibility\SmtpOutboundConfigRestrictFilterToVisibility;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Application\Policy\Filter\TenantAccesible;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Application\Policy\Fields\FixTenantExcludingRoot;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Application\Service\Visibility\SmtpOutboundConfigCollectNonEditableFields;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Application\Policy\Allow\Create\IsAuthenticatedCreateAllow;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Application\Usecase\Create\SmtpOutboundConfigCreateAllowDecision;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Application\Policy\Allow\Update\IsAuthenticatedUpdateAllow;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Application\Usecase\Update\SmtpOutboundConfigUpdateAllowDecision;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Application\Policy\Allow\Retrieve\IsAuthenticatedRetrieveAllow;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Application\Usecase\Retrieve\SmtpOutboundConfigRetrieveAllowDecision;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Application\Policy\Allow\List\IsAuthenticatedListAllow;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Application\Usecase\List\SmtpOutboundConfigListAllowDecision;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Application\Policy\Allow\Delete\IsAuthenticatedDeleteAllow;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Application\Usecase\Delete\SmtpOutboundConfigDeleteAllowDecision;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Infrastructure\Driven\SmtpOutboundConfigReadRepositoryAdapter;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Infrastructure\Driven\SmtpOutboundConfigWriteRepositoryAdapter;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\Gateway\SmtpOutboundConfigReadGateway;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\Gateway\SmtpOutboundConfigWriteGateway;

class SmtpOutboundConfigPlugin extends MicroPlugin
{
    #[Override]
    public function registerServiceDefinition(array $def): array
    {
        $def[SmtpOutboundConfigReadGateway::class] = \DI\autowire(SmtpOutboundConfigReadRepositoryAdapter::class);
        $def[SmtpOutboundConfigWriteGateway::class] = \DI\autowire(SmtpOutboundConfigWriteRepositoryAdapter::class);
        return $def;
    }
    #[Override]
    public function registerRoutes(RouteCollectorProxy $collector): void
    {
        $collector->group('/api/template/smtp-outbound-config', [$this, 'setRoutesForSmtpOutboundConfig']);
        $collector->group('/api/me/acl/template/smtp-outbound-config', [$this, 'setRoutesForSmtpOutboundConfigAcl']);
    }
    #[Override]
    public function registerEvents(EventListenersRegistrarInterface $listener): void
    {
        $listener->registerListener(SmtpOutboundConfigRestrictFilterToVisibility::class, TenantAccesible::class);
        $listener->registerListener(SmtpOutboundConfigCollectNonEditableFields::class, FixTenantExcludingRoot::class);
        $listener->registerListener(SmtpOutboundConfigCreateAllowDecision::class, IsAuthenticatedCreateAllow::class);
        $listener->registerListener(SmtpOutboundConfigUpdateAllowDecision::class, IsAuthenticatedUpdateAllow::class);
        $listener->registerListener(SmtpOutboundConfigRetrieveAllowDecision::class, IsAuthenticatedRetrieveAllow::class);
        $listener->registerListener(SmtpOutboundConfigListAllowDecision::class, IsAuthenticatedListAllow::class);
        $listener->registerListener(SmtpOutboundConfigDeleteAllowDecision::class, IsAuthenticatedDeleteAllow::class);
    }
    #[Override]
    public function registerStartup(StartupProcessor $processor): void
    {
        $processor->register(function (ContainerInterface $container) {
            $handler = $container->get(Handler::class);
            $handler->registerResourceAction("smtp-outbound-config", "list", "READ");
            $handler->registerResourceAction("smtp-outbound-config", "create", "WRITE");
            $handler->registerResourceAction("smtp-outbound-config", "retrieve", "READ");
            $handler->registerResourceAction("smtp-outbound-config", "update", "WRITE");
            $handler->registerResourceAction("smtp-outbound-config", "delete", "WRITE");

            $handler->registerResourceAttribute("smtp-outbound-config", "tenant", "MANAGE");
            $handler->registerResourceAttribute("smtp-outbound-config", "host", "MANAGE");
            $handler->registerResourceAttribute("smtp-outbound-config", "port", "MANAGE");
            $handler->registerResourceAttribute("smtp-outbound-config", "login", "MANAGE");
            $handler->registerResourceAttribute("smtp-outbound-config", "password", "MANAGE");
            $handler->registerResourceAttribute("smtp-outbound-config", "senderName", "MANAGE");
            $handler->registerResourceAttribute("smtp-outbound-config", "senderEmail", "MANAGE");
            $handler->registerResourceAttribute("smtp-outbound-config", "timeout", "MANAGE");
            $handler->registerResourceAttribute("smtp-outbound-config", "useTls", "MANAGE");
            $handler->registerResourceAttribute("smtp-outbound-config", "maxRetries", "MANAGE");
            $handler->registerResourceAttribute("smtp-outbound-config", "retryDelay", "MANAGE");
            $handler->registerResourceAttribute("smtp-outbound-config", "rateLimit", "MANAGE");
            $handler->registerResourceAttribute("smtp-outbound-config", "version", "MANAGE");
        }, StartupProcessor::before(SecurityPlugin::STARTUP_ORDER));
    }
    public function setRoutesForSmtpOutboundConfigAcl(RouteCollectorProxy $smtpOutboundConfigGroup): void
    {
        $smtpOutboundConfigGroup->get('', [SmtpOutboundConfigAllowController::class, 'genericAllow']);
        $smtpOutboundConfigGroup->get('/{uid}', [SmtpOutboundConfigAllowController::class, 'contextualAllow']);
    }
    public function setRoutesForSmtpOutboundConfig(RouteCollectorProxy $smtpOutboundConfigGroup): void
    {
        $smtpOutboundConfigGroup->get('', [SmtpOutboundConfigListController::class, 'list']);
        $smtpOutboundConfigGroup->post('', [SmtpOutboundConfigCreateController::class, 'create']);
        $smtpOutboundConfigGroup->get('/{uid}', [SmtpOutboundConfigRetrieveController::class, 'retrieve']);
        $smtpOutboundConfigGroup->put('/{uid}', [SmtpOutboundConfigUpdateController::class, 'update']);
        $smtpOutboundConfigGroup->delete('/{uid}', [SmtpOutboundConfigDeleteController::class, 'delete']);
        $smtpOutboundConfigGroup->delete('', [SmtpOutboundConfigDeleteController::class, 'deleteAllForQuery']);
        $smtpOutboundConfigGroup->get('/~/delete-status/{uid}', [SmtpOutboundConfigDeleteController::class, 'checkDeleteAllForQueryStatus']);
    }
}
